WITH unpacked AS (SELECT id, customer_id, created_at, coupon_codes, ship_to, attributes, COALESCE(ship_to.city, 'UNKNOWN') AS city_or_unknown, attributes['device'] AS device, ship_to.zip AS ship_zip, ship_to.city AS ship_city FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'VIP')) SELECT customer_id, DATE_TRUNC('DAY', created_at) AS activity_day, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min, COUNT(CASE WHEN ship_city = 'Bangkok' THEN 1 END) AS bangkok_count, COUNT_IF(ship_city = 'New York') AS new_york_events, COUNT_IF(ship_city = 'London') AS london_events, COUNT(CASE WHEN ship_city = 'New York' THEN 1 END) AS new_york_count FROM unpacked GROUP BY 1, 2 ORDER BY bangkok_count NULLS FIRST;
